-- Her Flight Deck — initial schema.
--
-- This file is the single source of truth for the database shape. It is
-- compiled into the Rust binary via include_str! and imported by the
-- TypeScript sql.js fallback via ?raw, so the two can never drift.
--
-- Conventions:
--   * ids are TEXT uuids generated by the application
--   * dates are 'YYYY-MM-DD', timestamps are ISO-8601 strings
--   * money is stored in whole cents as INTEGER to avoid float drift
--   * relationships are optional wherever the product allows them to be

-- Profile / application settings. Single row, id = 'profile'.
CREATE TABLE settings (
  id                   TEXT PRIMARY KEY,
  pilot_name           TEXT NOT NULL DEFAULT '',
  certificate_goal     TEXT NOT NULL DEFAULT 'Private Pilot',
  current_focus        TEXT NOT NULL DEFAULT '',
  current_milestone_id TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);

-- Training journey. Ordered stages the user is working through.
CREATE TABLE milestones (
  id          TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  position    INTEGER NOT NULL DEFAULT 0,
  status      TEXT NOT NULL DEFAULT 'not_started',
  target_date TEXT,
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);

CREATE TABLE goals (
  id           TEXT PRIMARY KEY,
  milestone_id TEXT REFERENCES milestones(id) ON DELETE SET NULL,
  title        TEXT NOT NULL,
  description  TEXT NOT NULL DEFAULT '',
  status       TEXT NOT NULL DEFAULT 'not_started',
  priority     TEXT NOT NULL DEFAULT 'important',
  target_date  TEXT,
  notes        TEXT NOT NULL DEFAULT '',
  confidence   INTEGER,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL,
  completed_at TEXT
);
CREATE INDEX idx_goals_milestone ON goals(milestone_id);
CREATE INDEX idx_goals_status ON goals(status);

CREATE TABLE goal_checklist_items (
  id         TEXT PRIMARY KEY,
  goal_id    TEXT NOT NULL REFERENCES goals(id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  done       INTEGER NOT NULL DEFAULT 0,
  position   INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_checklist_goal ON goal_checklist_items(goal_id);

-- Schedule events. Flight lessons, study sessions, tests, deadlines.
CREATE TABLE schedule_events (
  id             TEXT PRIMARY KEY,
  title          TEXT NOT NULL,
  event_type     TEXT NOT NULL DEFAULT 'flight_lesson',
  date           TEXT NOT NULL,
  start_time     TEXT,
  end_time       TEXT,
  location       TEXT NOT NULL DEFAULT '',
  instructor     TEXT NOT NULL DEFAULT '',
  notes          TEXT NOT NULL DEFAULT '',
  goal_id        TEXT REFERENCES goals(id) ON DELETE SET NULL,
  estimated_cost INTEGER,
  actual_cost    INTEGER,
  status         TEXT NOT NULL DEFAULT 'scheduled',
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL
);
CREATE INDEX idx_events_date ON schedule_events(date);
CREATE INDEX idx_events_status ON schedule_events(status);

CREATE TABLE event_prep_items (
  id         TEXT PRIMARY KEY,
  event_id   TEXT NOT NULL REFERENCES schedule_events(id) ON DELETE CASCADE,
  title      TEXT NOT NULL,
  done       INTEGER NOT NULL DEFAULT 0,
  position   INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);
CREATE INDEX idx_prep_event ON event_prep_items(event_id);

-- Study Library. Files live on disk in private app data; only metadata
-- and a relative path are stored here.
CREATE TABLE study_materials (
  id                 TEXT PRIMARY KEY,
  title              TEXT NOT NULL,
  material_type      TEXT NOT NULL DEFAULT 'study_guide',
  topic              TEXT NOT NULL DEFAULT 'general',
  review_status      TEXT NOT NULL DEFAULT 'needs_review',
  priority           TEXT NOT NULL DEFAULT 'later',
  goal_id            TEXT REFERENCES goals(id) ON DELETE SET NULL,
  event_id           TEXT REFERENCES schedule_events(id) ON DELETE SET NULL,
  notes              TEXT NOT NULL DEFAULT '',
  file_path          TEXT,
  original_file_name TEXT,
  file_size          INTEGER,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL,
  last_reviewed_at   TEXT
);
CREATE INDEX idx_materials_status ON study_materials(review_status);
CREATE INDEX idx_materials_topic ON study_materials(topic);
CREATE INDEX idx_materials_goal ON study_materials(goal_id);

CREATE TABLE tags (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);

CREATE TABLE material_tags (
  material_id TEXT NOT NULL REFERENCES study_materials(id) ON DELETE CASCADE,
  tag_id      TEXT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (material_id, tag_id)
);

-- Materials attached to a lesson for preparation.
CREATE TABLE event_materials (
  event_id    TEXT NOT NULL REFERENCES schedule_events(id) ON DELETE CASCADE,
  material_id TEXT NOT NULL REFERENCES study_materials(id) ON DELETE CASCADE,
  PRIMARY KEY (event_id, material_id)
);

-- Next Actions: the shared action system used across the whole product.
CREATE TABLE next_actions (
  id                TEXT PRIMARY KEY,
  title             TEXT NOT NULL,
  description       TEXT NOT NULL DEFAULT '',
  category          TEXT NOT NULL DEFAULT 'prepare',
  priority          TEXT NOT NULL DEFAULT 'important',
  status            TEXT NOT NULL DEFAULT 'open',
  due_date          TEXT,
  estimated_minutes INTEGER,
  related_type      TEXT,
  related_id        TEXT,
  created_at        TEXT NOT NULL,
  updated_at        TEXT NOT NULL,
  completed_at      TEXT
);
CREATE INDEX idx_actions_status ON next_actions(status);
CREATE INDEX idx_actions_due ON next_actions(due_date);
CREATE INDEX idx_actions_related ON next_actions(related_type, related_id);

CREATE TABLE journal_entries (
  id                      TEXT PRIMARY KEY,
  event_id                TEXT REFERENCES schedule_events(id) ON DELETE SET NULL,
  date                    TEXT NOT NULL,
  title                   TEXT NOT NULL DEFAULT '',
  mission                 TEXT NOT NULL DEFAULT '',
  practiced               TEXT NOT NULL DEFAULT '',
  went_well               TEXT NOT NULL DEFAULT '',
  was_difficult           TEXT NOT NULL DEFAULT '',
  instructor_feedback     TEXT NOT NULL DEFAULT '',
  questions_for_next_time TEXT NOT NULL DEFAULT '',
  confidence              INTEGER,
  goal_id                 TEXT REFERENCES goals(id) ON DELETE SET NULL,
  created_at              TEXT NOT NULL,
  updated_at              TEXT NOT NULL
);
CREATE INDEX idx_journal_date ON journal_entries(date);

CREATE TABLE journal_materials (
  journal_id  TEXT NOT NULL REFERENCES journal_entries(id) ON DELETE CASCADE,
  material_id TEXT NOT NULL REFERENCES study_materials(id) ON DELETE CASCADE,
  PRIMARY KEY (journal_id, material_id)
);

CREATE TABLE questions (
  id          TEXT PRIMARY KEY,
  text        TEXT NOT NULL,
  topic       TEXT NOT NULL DEFAULT 'general',
  event_id    TEXT REFERENCES schedule_events(id) ON DELETE SET NULL,
  material_id TEXT REFERENCES study_materials(id) ON DELETE SET NULL,
  journal_id  TEXT REFERENCES journal_entries(id) ON DELETE SET NULL,
  status      TEXT NOT NULL DEFAULT 'to_ask',
  answer      TEXT NOT NULL DEFAULT '',
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL,
  answered_at TEXT
);
CREATE INDEX idx_questions_status ON questions(status);

-- Training finances. Amounts are whole cents.
CREATE TABLE transactions (
  id          TEXT PRIMARY KEY,
  type        TEXT NOT NULL,
  amount      INTEGER NOT NULL,
  date        TEXT NOT NULL,
  category    TEXT NOT NULL DEFAULT 'other',
  description TEXT NOT NULL DEFAULT '',
  notes       TEXT NOT NULL DEFAULT '',
  event_id    TEXT REFERENCES schedule_events(id) ON DELETE SET NULL,
  goal_id     TEXT REFERENCES goals(id) ON DELETE SET NULL,
  source      TEXT NOT NULL DEFAULT 'manual',
  created_at  TEXT NOT NULL,
  updated_at  TEXT NOT NULL
);
CREATE INDEX idx_transactions_date ON transactions(date);
CREATE INDEX idx_transactions_type ON transactions(type);

-- A lesson may have many manual expenses, but the "record the lesson cost"
-- convenience flow may only ever create one. This makes the duplicate
-- impossible at the storage layer rather than only in the UI.
CREATE UNIQUE INDEX idx_transactions_one_lesson_cost
  ON transactions(event_id)
  WHERE source = 'lesson_cost' AND event_id IS NOT NULL;

CREATE TABLE fund_goals (
  id         TEXT PRIMARY KEY,
  title      TEXT NOT NULL,
  target     INTEGER NOT NULL,
  active     INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
